@import url("https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400..600;1,6..72,400..500&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Public+Sans:ital,wght@0,400..700;1,400..500&display=swap");
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Margin: paper and ink for people who read closely and write things down.
  The page is a warm paper, cards a lighter sheet, and hairline rules divide
  them the way ruled lines divide a legal pad. Ink is a deep blue-black.
  Colour is spent sparingly: an oxblood for the main action and the
  selection, and three muted marks for status, olive for settled, slate for
  pending and amber for a deadline. Headings and entry titles set in a book
  serif, the interface in a plain grotesque, line numbers in a typewriter
  mono. Corners stay near square, and only a floating menu casts a shadow.

  The `.dark` block flips every token at once, so components never branch on
  the theme: --*-face hold the fills, --*-edge the rules around them.
*/

:root {
  /* ─── Paper: a warm page, a lighter sheet, one hairline between ─── */
  --background: oklch(0.975 0.012 85);
  --foreground: oklch(0.24 0.02 260);
  --card: oklch(0.99 0.008 85);
  --card-foreground: oklch(0.24 0.02 260);
  --popover: oklch(0.99 0.008 85);
  --popover-foreground: oklch(0.24 0.02 260);

  /* ─── The action: oxblood ink ─── */
  --primary: oklch(0.42 0.13 25);
  --primary-foreground: oklch(0.985 0.01 85);
  --primary-text: oklch(0.42 0.13 25);             /* oxblood as text on paper */

  --secondary: oklch(0.955 0.014 85);               /* the matter rail */
  --secondary-foreground: oklch(0.24 0.02 260);
  --muted: oklch(0.955 0.014 85);                   /* the desk under the sheet */
  --muted-foreground: oklch(0.46 0.02 260);
  --accent: oklch(0.935 0.016 85);                  /* hover and highlighted rows */
  --accent-foreground: oklch(0.24 0.02 260);

  --destructive: oklch(0.52 0.18 29);
  --destructive-foreground: oklch(0.985 0.01 85);
  --success: oklch(0.5 0.09 115);                   /* olive: settled */
  --success-foreground: oklch(0.985 0.01 85);
  --warning: oklch(0.74 0.13 75);                   /* amber: a deadline */
  --warning-foreground: oklch(0.24 0.02 260);
  --info: oklch(0.5 0.05 245);                      /* slate: pending */
  --info-foreground: oklch(0.985 0.01 85);

  --border: oklch(0.89 0.014 85);                   /* the ruled hairline */
  --input: oklch(0.82 0.016 85);                    /* the firmer rule on controls */
  --ring: oklch(0.42 0.13 25 / 0.32);

  /* ─── Status marks: muted inks for settled, pending, deadline, overdue ─── */
  --olive: oklch(0.55 0.09 115);
  --slate: oklch(0.52 0.05 245);
  --amber: oklch(0.74 0.13 75);
  --rust: oklch(0.58 0.12 45);
  --scrim: oklch(0.24 0.02 260 / 0.32);

  /* ─── The mark: a pale oxblood wash for issue tags and small labels ─── */
  --mark: oklch(0.895 0.04 28);
  --mark-foreground: oklch(0.38 0.12 25);

  /* ─── Status text on a marked label: deep in its own hue ─── */
  --success-text: oklch(0.4 0.08 115);
  --warning-text: oklch(0.4 0.09 70);
  --destructive-text: oklch(0.45 0.16 28);
  --info-text: oklch(0.4 0.05 245);
  --olive-text: oklch(0.4 0.08 115);
  --slate-text: oklch(0.4 0.05 245);
  --amber-text: oklch(0.4 0.09 70);
  --rust-text: oklch(0.39 0.1 40);
  --field: oklch(0.99 0.008 85);                    /* a field is a clean sheet */

  /* ─── Faces and rules: flat inks, no light, no drop ─── */
  /* The primary button: flat oxblood inside a darker rule. */
  --ox-face: linear-gradient(oklch(0.42 0.13 25), oklch(0.42 0.13 25));
  --ox-face-hover: linear-gradient(oklch(0.37 0.12 25), oklch(0.37 0.12 25));
  --ox-edge: 0 0 0 0.0625rem oklch(0.35 0.11 25);
  /* The darker rule on its own, around a paper thumb. */
  --ox-hairline: 0 0 0 0.0625rem oklch(0.35 0.11 25);
  /* The marked call to action: the pale wash inside a faint oxblood rule. */
  --mark-face: linear-gradient(oklch(0.895 0.04 28), oklch(0.895 0.04 28));
  --mark-edge: inset 0 0 0 0.0625rem oklch(0.42 0.13 25 / 0.2);
  /* The toolbar tab: a ruled sheet with no shadow at all. */
  --pill-face-hover: oklch(0.955 0.014 85);
  --pill-edge: inset 0 0 0 0.0625rem oklch(0.82 0.016 85);
  --pill-edge-hover: inset 0 0 0 0.0625rem oklch(0.72 0.02 85);
  /* The quiet face: a step of paper, no shade. */
  --field-hover: oklch(0.965 0.012 85);
  --field-shade: inset 0 0 0 0 oklch(0 0 0 / 0);
  /* The slot a switch or slider track sits in: a rule dark enough to hold
     3:1 against the page and the sheet (WCAG 1.4.11). */
  --slot-edge: inset 0 0 0 0.0625rem oklch(0.57 0.02 80);
  /* An empty checkbox or radio: the same firm rule. */
  --control-edge: inset 0 0 0 0.0625rem oklch(0.56 0.02 80);
  --control-edge-hover: inset 0 0 0 0.0625rem oklch(0.42 0.02 260);
  /* A text field: a clean sheet inside a firm rule. */
  --field-edge: inset 0 0 0 0.0625rem oklch(0.6 0.02 80);
  /* The selected sheet: one oxblood rule inside the edge. */
  --selected-edge: inset 0 0 0 0.09375rem oklch(0.42 0.13 25);
  --destructive-face: linear-gradient(oklch(0.52 0.18 29), oklch(0.52 0.18 29));

  /* ─── Clause: the inks a quoted passage or a listing is set in ─── */
  --clause-comment: oklch(0.55 0.015 85);
  --clause-keyword: oklch(0.42 0.13 25);
  --clause-control: oklch(0.45 0.1 40);
  --clause-ident: oklch(0.4 0.05 245);
  --clause-fn: oklch(0.4 0.05 245);
  --clause-string: oklch(0.42 0.08 115);
  --clause-doc: oklch(0.45 0.07 115);
  --clause-number: oklch(0.47 0.1 65);
  --clause-escape: oklch(0.45 0.05 245);
  --clause-op: oklch(0.42 0.02 260);
  --clause-key: oklch(0.42 0.13 25);
  --clause-gutter: oklch(0.58 0.015 85);

  /* ─── Type: a book serif for headings, a plain grotesque for the interface ─── */
  --font-sans: "Public Sans", ui-sans-serif, system-ui, sans-serif;
  --font-serif: "Newsreader", "Iowan Old Style", Georgia, ui-serif, serif;
  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, Consolas, monospace;

  /* ─── Radius: near square, a touch softer on sheets ─── */
  --radius: 0.25rem;
  --radius-sm: 0.125rem;   /* checkboxes, the tag remove button */
  --radius-md: 0.1875rem;  /* labels, menu rows */
  --radius-lg: 0.25rem;    /* buttons, fields, tabs */
  --radius-xl: 0.375rem;   /* cards, menus, clause blocks */
  --radius-2xl: 0.375rem;  /* larger popovers */
  --radius-3xl: 0.5rem;    /* dialogs and the app shell */

  /* ─── Motion: the soft profile, calm enough to read through ─── */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  --shadow-xs: 0 0.0625rem 0 oklch(0.24 0.02 260 / 0.04);
  --shadow-sm: var(--pill-edge);
  --shadow-md: var(--shadow-menu);
  --shadow-lg:
    0 0 0 0.0625rem oklch(0.24 0.02 260 / 0.1),
    0 1rem 2.5rem -1.25rem oklch(0.24 0.02 260 / 0.22);
  --shadow-card: 0 0 0 0.0625rem oklch(0.89 0.014 85);
  --shadow-menu:
    0 0 0 0.0625rem oklch(0.24 0.02 260 / 0.1),
    0 0.5rem 1.5rem -0.5rem oklch(0.24 0.02 260 / 0.18);
  --shadow-overlay: var(--shadow-lg);
  --shadow-thumb:
    0 0 0 0.0625rem oklch(0.56 0.02 80),
    0 0.0625rem 0.125rem oklch(0.24 0.02 260 / 0.12);

  --chart-1: oklch(0.42 0.13 25);
  --chart-2: oklch(0.52 0.05 245);
  --chart-3: oklch(0.55 0.09 115);
  --chart-4: oklch(0.7 0.13 75);
  --chart-5: oklch(0.58 0.12 45);

  --ai-label: oklch(0.94 0.04 80);
  --ai-label-foreground: oklch(0.45 0.09 70);
}

/*
  Dark: the same notebook under a desk lamp. The paper turns to a deep ink
  blue, the ink to a warm cream, and the oxblood lifts a step so it still
  reads as the one action.
*/
.dark {
  --background: oklch(0.2 0.012 260);
  --foreground: oklch(0.92 0.015 85);
  --card: oklch(0.23 0.014 260);
  --card-foreground: oklch(0.92 0.015 85);
  --popover: oklch(0.24 0.014 260);
  --popover-foreground: oklch(0.92 0.015 85);

  --primary: oklch(0.52 0.14 25);
  --primary-foreground: oklch(0.98 0.01 85);
  --primary-text: oklch(0.76 0.1 25);

  --secondary: oklch(0.18 0.012 260);
  --secondary-foreground: oklch(0.92 0.015 85);
  --muted: oklch(0.18 0.012 260);
